#!/usr/bin/env node
// ============================================================
// Codegen: src/lib/eventTypes.js  ->  lambda/events/eventTypes.generated.js
// ============================================================
// V3-EVENT-008. The deployed events Lambda is a STANDALONE zip with no bundler,
// so it CANNOT import from src/lib/ at runtime. This script copies the canonical
// event-type vocabulary into a sibling ESM file inside lambda/events/ that the
// Lambda CAN import. The generated file is COMMITTED so dev + vitest run against
// a real artifact (not a phantom).
//
// Run via `npm run gen:event-types`. CI verifies no drift via
// `npm run check:event-types` (regenerate to a temp file, diff, fail on diff),
// and the deploy workflow regenerates immediately before zipping the events fn.
//
// --check : write to a temp path and exit 1 if it differs from the committed file
//           (used by check:event-types). Without --check, overwrite in place.

import { readFileSync, writeFileSync, mkdtempSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { tmpdir } from 'node:os'

const __dirname = dirname(fileURLToPath(import.meta.url))
const repoRoot = join(__dirname, '..')
const SRC = join(repoRoot, 'src', 'lib', 'eventTypes.js')
const OUT = join(repoRoot, 'lambda', 'events', 'eventTypes.generated.js')

// Import the canonical module by absolute file URL (zero-dep, so this just works).
const canon = await import('file://' + SRC)
const {
  EVENT_TYPES, BATCH_EXCLUDED_TYPES, BATCH_EVENT_TYPES,
  // V4-WATERMATH-001 F0. These three cross the same bundler-less boundary as the vocabulary and
  // for the same reason: validators.js enforces them at the API edge and CANNOT import src/lib/.
  NON_REWARD_EVENT_TYPES, WATER_DEPTH_CLASSES, WATER_DEPTH_SOURCES,
  // V4-LOSSEVENT-001. Same boundary, same reason: validators.js enforces the reduction contract at
  // the API edge and the events Lambda is a bundler-less zip, so it cannot import src/lib/.
  PLANT_REDUCTION_EVENT_TYPES, LOSS_REASONS, GIVEAWAY_REASONS,
  REDUCTION_QTY_KEY, LOSS_REASON_KEY, GIVEAWAY_REASON_KEY,
} = canon

function emit(arr) {
  return '[\n' + arr.map((v) => `  '${v}',`).join('\n') + '\n]'
}

// Stamp the source mtime-independent hash-ish marker via the source byte length so a
// reviewer can eyeball whether the generated file tracks the source revision.
const srcBytes = readFileSync(SRC, 'utf8').length

const banner = `// ============================================================
// AUTO-GENERATED by scripts/gen-lambda-event-types.mjs — DO NOT EDIT BY HAND.
// ============================================================
// Source of truth: src/lib/eventTypes.js (canonical, zero-import).
// Regenerate: \`npm run gen:event-types\`. Drift is CI-enforced by
// \`npm run check:event-types\` (fails the build on any divergence) and the
// deploy workflow regenerates this immediately before zipping the events Lambda.
//
// WHY this file exists: the events Lambda ships as a standalone zip with NO
// bundler, so it cannot import from src/lib/ at runtime. validators.js imports
// THIS sibling instead. (Source byte-length at generation: ${srcBytes}.)
`

const body = `${banner}
export const EVENT_TYPES = ${emit(EVENT_TYPES)}

export const BATCH_EXCLUDED_TYPES = ${emit(BATCH_EXCLUDED_TYPES)}

// Derived (EVENT_TYPES minus BATCH_EXCLUDED_TYPES) — kept explicit here so the
// Lambda needs no runtime filtering and the committed artifact is the contract.
export const BATCH_EVENT_TYPES = ${emit(BATCH_EVENT_TYPES)}

// V4-WATERMATH-001 F0 — event types that grant ZERO xp / streak / total_events.
// Enforced ONLY in application code (live Neon has no reward trigger on event_log);
// see the long note in src/lib/eventTypes.js for the three enforcement points.
export const NON_REWARD_EVENT_TYPES = ${emit(NON_REWARD_EVENT_TYPES)}

export function isRewardedEventType(eventType) {
  return !NON_REWARD_EVENT_TYPES.includes(eventType)
}

// V4-WATERMATH-001 F0 — metadata.water_depth / metadata.water_depth_source vocabularies.
export const WATER_DEPTH_CLASSES = ${emit(WATER_DEPTH_CLASSES)}

export const WATER_DEPTH_SOURCES = ${emit(WATER_DEPTH_SOURCES)}

// V4-LOSSEVENT-001 — plant-reduction ledger. The two vocabularies are SEPARATE on purpose: a gift
// is not a loss, and keeping loss_reason off given_away rows is what stops a loss aggregate from
// counting one. See src/lib/eventTypes.js for the full contract.
export const PLANT_REDUCTION_EVENT_TYPES = ${emit(PLANT_REDUCTION_EVENT_TYPES)}

export const LOSS_REASONS = ${emit(LOSS_REASONS)}

export const GIVEAWAY_REASONS = ${emit(GIVEAWAY_REASONS)}

export const REDUCTION_QTY_KEY = '${REDUCTION_QTY_KEY}'
export const LOSS_REASON_KEY = '${LOSS_REASON_KEY}'
export const GIVEAWAY_REASON_KEY = '${GIVEAWAY_REASON_KEY}'

export const REDUCTION_REASON_KEY_BY_TYPE = {
  failed: LOSS_REASON_KEY,
  given_away: GIVEAWAY_REASON_KEY,
}

export const REDUCTION_REASONS_BY_KEY = {
  [LOSS_REASON_KEY]: LOSS_REASONS,
  [GIVEAWAY_REASON_KEY]: GIVEAWAY_REASONS,
}

export function isPlantReductionEventType(eventType) {
  return PLANT_REDUCTION_EVENT_TYPES.includes(eventType)
}

// Only a LOSS accrues into plants.qty_lost — a given-away plant is alive somewhere else.
export function accruesQtyLost(eventType) {
  return eventType === 'failed'
}
`

const isCheck = process.argv.includes('--check')

if (isCheck) {
  const current = readFileSync(OUT, 'utf8')
  if (current !== body) {
    const tmp = join(mkdtempSync(join(tmpdir(), 'evtgen-')), 'eventTypes.generated.js')
    writeFileSync(tmp, body)
    console.error('DRIFT: lambda/events/eventTypes.generated.js is out of sync with src/lib/eventTypes.js')
    console.error(`Expected (regenerated) written to: ${tmp}`)
    console.error('Run `npm run gen:event-types` and commit the result.')
    process.exit(1)
  }
  console.log('OK: eventTypes.generated.js is in sync with src/lib/eventTypes.js')
  process.exit(0)
}

writeFileSync(OUT, body)
console.log(`Wrote ${OUT} (${BATCH_EVENT_TYPES.length} batch types, ${EVENT_TYPES.length} total).`)
